"use client"
import { useRef, useState } from "react"

export default function BeforeAfter({
  before,
  after,
}: {
  before: string
  after: string
}) {
  const [pos, setPos] = useState(50)
  const ref = useRef<HTMLDivElement>(null)

  const move = (x: number) => {
    const r = ref.current!.getBoundingClientRect()
    setPos(Math.min(100, Math.max(0, ((x - r.left) / r.width) * 100)))
  }

  return (
    <div
      ref={ref}
      className="relative h-[513px] w-[600px] shrink-0 cursor-ew-resize touch-none select-none overflow-hidden rounded-[24px]"
      onPointerDown={(e) => {
        e.currentTarget.setPointerCapture(e.pointerId)
        move(e.clientX)
      }}
      onPointerMove={(e) => e.buttons === 1 && move(e.clientX)}
    >
      <img src={after} alt="Final UI" draggable={false} className="absolute inset-0 size-full object-cover" />
      <div className="absolute inset-0" style={{ clipPath: `inset(0 ${100 - pos}% 0 0)` }}>
        <img src={before} alt="Wireframe" draggable={false} className="absolute inset-0 size-full object-cover" />
      </div>

      <span className="absolute left-[16px] top-[18px] rounded-[16px] bg-white px-[14px] py-[5px] text-[12px] text-[#1a0e14] shadow-[0_3.5px_10.4px_rgba(0,0,0,0.08)]">
        Wireframe
      </span>
      <span className="absolute right-[16px] top-[18px] rounded-[16px] bg-white px-[14px] py-[5px] text-[12px] text-[#1a0e14] shadow-[0_3.5px_10.4px_rgba(0,0,0,0.08)]">
        Final UI
      </span>

      <div className="absolute inset-y-0 w-[2px] -translate-x-1/2 bg-[#7a0d3b]" style={{ left: `${pos}%` }} />
      <div
        className="absolute top-1/2 flex size-[37px] -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full border-[2.6px] border-solid border-white bg-[#7a0d3b] text-[12px] text-white"
        style={{ left: `${pos}%` }}
      >
        ‹ ›
      </div>
    </div>
  )
}